export function nodeFetchResponseToReadableStream(
  nodeStream: Readable,
  onError?: (err: LatitudeApiError) => void,
) {
  return new ReadableStream({
    start(controller) {
      /**
       * chunk <Buffer> | <string> | <any> The chunk of data.
       *  For streams that are not operating in object mode, the chunk will be either a string or Buffer.
       *  For streams that are in object mode, the chunk can be any JavaScript value other than null.
       *
       * The 'data' event is emitted whenever the stream is relinquishing ownership of a chunk of data to a consumer.
       */
      nodeStream.on('data', (chunk: Buffer) => {
        controller.enqueue(chunk)
      })

      /**
       * The 'end' event is emitted when there is no more data to be consumed from the stream.
       * The 'end' event will not be emitted unless the data is completely consumed.
       * This can be accomplished by switching the stream into flowing mode, or by calling stream.read() repeatedly until all data has been consumed.
       */
      nodeStream.on('end', () => {
        controller.close()
      })

      /**
       * The 'close' event is emitted when the stream and any of its
       * underlying resources (a file descriptor, for example) have been closed.
       * The event indicates that no more events will be emitted, and no further computation will occur.
       *
       * A Readable stream will always emit the 'close' event if it is created with the emitClose option.
       */
      nodeStream.on('close', () => {
        // Optionally handle the case when the stream closes unexpectedly
        if (!nodeStream.readableEnded) {
          controller.close()
        }
      })

      /**
       * The 'error' event may be emitted by a Readable implementation at any time.
       * Typically, this may occur if the underlying stream is unable to generate data due to
       * an underlying internal failure, or when a stream implementation attempts to push an invalid chunk of data.
       */
      nodeStream.on('error', (err) => {
        try {
          controller.error(err)
        } catch (e) {
          // controller might be closed already
          if (onError) {
            const error = new LatitudeApiError({
              status: 500,
              message: err.message,
              serverResponse: err.stack ?? '',
              errorCode: ApiErrorCodes.InternalServerError,
            })
            onError(error)
          }
        }
      })
    },
  })
}
import { Readable } from 'stream'

import type { Message } from '@latitude-data/compiler'
import {
  ApiErrorCodes,
  LatitudeApiError,
  RunErrorCodes,
} from '$sdk/utils/errors'
import { nodeFetchResponseToReadableStream } from '$sdk/utils/nodeFetchResponseToReadableStream'
import { StreamResponseCallbacks } from '$sdk/utils/types'
import { ParsedEvent, ReconnectInterval } from 'eventsource-parser'
import { EventSourceParserStream } from 'eventsource-parser/stream'
import {
  ChainCallResponseDto,
  ChainEventDto,
  StreamEventTypes,
} from '@latitude-data/constants/ai'

function parseJSON(line: string) {
  try {
    return JSON.parse(line) as ChainEventDto
  } catch (e) {
    // do nothing
  }
}

export async function handleStream({
  body,
  onEvent,
  onFinished,
  onError,
}: StreamResponseCallbacks & {
  body: Readable
}) {
  let conversation: Message[] = []
  let uuid: string | undefined
  let chainResponse: ChainCallResponseDto | undefined

  const parser = new EventSourceParserStream()
  const stream = nodeFetchResponseToReadableStream(body, onError)
  const eventStream = stream
    .pipeThrough(new TextDecoderStream())
    .pipeThrough(parser)

  try {
    for await (const event of eventStream as unknown as AsyncIterable<
      ParsedEvent | ReconnectInterval
    >) {
      const parsedEvent = event as ParsedEvent | ReconnectInterval

      if (parsedEvent.type === 'event') {
        const data = parseJSON(parsedEvent.data)

        if (!data) {
          throw new LatitudeApiError({
            status: 402,
            message: `Invalid JSON in server event:\n${parsedEvent.data}`,
            serverResponse: parsedEvent.data,
            errorCode: ApiErrorCodes.InternalServerError,
          })
        }

        if (parsedEvent.event === 'latitude-event') {
          if (data.type === 'chain-error') {
            throw new LatitudeApiError({
              status: 402,
              message: data.error.message,
              serverResponse: JSON.stringify(data.error),
              errorCode: RunErrorCodes.AIRunError,
            })
          }

          const messages =
            'messages' in data ? (data.messages! as Message[]) : []

          if (messages.length > 0) {
            conversation.push(...messages)
          }

          if (data.type === 'chain-complete') {
            uuid = data.uuid!
            chainResponse = data.response!
          }
        }

        onEvent?.({ event: parsedEvent.event as StreamEventTypes, data })
      }
    }

    if (!uuid || !chainResponse) {
      throw new Error(
        'Stream ended without a chain-complete event. Missing uuid or response.',
      )
    }

    const finalResponse = {
      conversation,
      uuid,
      response: chainResponse,
    }

    onFinished?.(finalResponse)

    return finalResponse
  } catch (e) {
    let error: LatitudeApiError

    if (e instanceof LatitudeApiError) {
      error = e as LatitudeApiError
    } else {
      const err = e as Error
      error = new LatitudeApiError({
        status: 402,
        message: err.message,
        serverResponse: err.stack ?? '',
        errorCode: ApiErrorCodes.InternalServerError,
      })
    }
    onError?.(error)
  }
}
